import { findProblemBySlug, problems, type Problem, } from "@/data/locales/en";
type PageProps = {
    params: Promise<{
        slug: string;
    }>;
};
export function generateStaticParams() {
    return problems.map((problem) => ({
        slug: problem.slug,
    }));
}
export async function generateMetadata({ params, }: PageProps): Promise<Metadata> {
    const { slug } = await params;
    const problem = findProblemBySlug(slug);
    if (!problem) {
        return {
            title: "No problem found | PC FIX",
            robots: {
                index: false,
                follow: false,
            },
        };
    }
    return {
        title: problem.seoTitle,
        alternates: languageAlternates(`/en/problems/${problem.slug}`),
        description: problem.seoDescription,
        robots: {
            index: true,
            follow: true,
        },
        openGraph: {
            title: problem.seoTitle,
            description: problem.seoDescription,
            type: "article",
            siteName: "PC FIX",
        },
    };
}
